/**
 * 负责死亡枪工具定义、校验、原单枪消费与追加死亡提案。输入为死亡上下文、当前枪权和选择，输出为校验结果及带原生命的追加提案。
 * 预检不付款，角色死亡流程复验后消费；目标死亡与最终判胜仍由有序中央结算负责。
 */
import { openDemonHunterStockFrame } from "./demon_hunter/authority";
import { captureNightLife, livingNightLife } from "../../../core/domain/night_effects";
import { AliveComponent, aliveLifeVersion } from "../../../core/domain/components/alive";
import { COMPONENT } from "../../../core/domain/components/names";
import { RoleComponent } from "../../../core/domain/components/role";
import {
  DeathCause,
  permitsDeathShot,
  type DeathActionPolicy,
  type EntityId,
  type GameEvent,
  type Role,
  type DeathSources,
  type DeathShotSelection,
} from "../../../core/domain/model";
import type { World } from "../../../core/domain/world";
import type { DeathHookResult, DeathHookContext } from "../hooks/hook_registry";
import { RuleError } from "@ai-werewolf-arena/game-contract";
import type { ToolSpec } from "../contracts";
import type { ToolRepairPack } from "../llm/contracts";
import { numberOrNull } from "../llm/helpers";
import { isAliveTarget, type ValidationRuleContext } from "../validation/contracts";

/** 原生工具元数据不绑定特定角色；SDK／MCP 文案与玩家提示由本地化入口提供。 */
export const DEATH_SHOT_TOOL_SPECS: ToolSpec[] = [
  {
    name: "shoot",
    parameters: {
      type: "object",
      properties: {
        target_id: {
          type: ["number", "null"],
        },
      },
      required: ["target_id"],
      additionalProperties: false,
    },
    argHint: 'shoot args: {"target_id":number|null}',
    userPromptHintKey: "action.shoot.hint",
  },
];
export const DEATH_SHOT_REPAIR: ToolRepairPack = {
  coerce: {
    shoot: (args) => {
      if (args.target_id === null) return { target_id: null };
      const target = numberOrNull(args.target_id);
      return target === null ? null : { target_id: target };
    },
  },
};
export function validateDeathShot(ctx: ValidationRuleContext, hasShot: boolean) {
  if (!hasShot) return { code: RuleError.ShootUnavailable };
  if (ctx.toolCall.name !== "shoot") return { code: RuleError.ToolMismatch };
  if (
    ctx.toolCall.args.target_id !== null &&
    !isAliveTarget(ctx.world, ctx.toolCall.args.target_id)
  )
    return { code: RuleError.ShootTarget };
  return null;
}

interface DeathShotRules {
  role: Role;
  state: (
    role: RoleComponent,
  ) => { readonly canShoot: boolean; readonly deathActionPolicy?: DeathActionPolicy } | undefined;
  policy?: (state: {
    readonly canShoot: boolean;
    readonly deathActionPolicy?: DeathActionPolicy;
  }) => DeathActionPolicy;
  permits: (sources: readonly DeathCause[]) => boolean;
  shotEvent: (actorId: EntityId, targetId: EntityId) => GameEvent;
  poisonEvent?: (actorId: EntityId) => GameEvent;
}

/** 共用原单枪消费；实际目标死亡和最终判胜仍归中央结算。 */
export async function resolveDeathShots(
  world: World,
  deadIds: EntityId[],
  deathSources: DeathSources,
  choose: (actorId: EntityId) => Promise<DeathShotSelection>,
  events: GameEvent[],
  rules: DeathShotRules,
  context?: DeathHookContext,
): Promise<DeathHookResult> {
  const result: DeathHookResult = { extraDeaths: [], extraDeathSources: {} };
  for (const actorId of deadIds) {
    if (context?.isCurrent && !context.isCurrent()) break;
    const role = world.getComponent(actorId, COMPONENT.Role);
    const state = role ? rules.state(role) : undefined;
    if (
      !role ||
      role.role !== rules.role ||
      !state ||
      world.getComponent(actorId, COMPONENT.Alive)?.alive !== false
    )
      continue;
    const stock = rules.role === "hunter" ? openDemonHunterStockFrame(world, actorId, state) : null;
    const consume = () => {
      if (stock) stock.consume();
      else (state as { canShoot: boolean }).canShoot = false;
    };
    const sources = deathSources[actorId] ?? [];
    if (sources.includes(DeathCause.Poison)) {
      consume();
      if (rules.poisonEvent) events.push(rules.poisonEvent(actorId));
      continue;
    }
    const policy = rules.policy?.(state);
    const deathPhase = context?.deathOriginPhase;
    const nightEffect = context?.nightEffect;
    const causeIdentity = JSON.stringify(sources);
    if (
      !state.canShoot ||
      !rules.permits(sources) ||
      (policy !== undefined && !permitsDeathShot(sources, policy, deathPhase))
    ) {
      consume();
      continue;
    }
    const actorLife = world.getComponent(actorId, COMPONENT.Alive)!;
    const actorVersion = aliveLifeVersion(actorLife);
    const camp = role.camp,
      privateState = role.privateState;
    const targets = new Map(
      world.getAliveEntityIds().map((id) => [id, captureNightLife(world, id)]),
    );
    const selected = await choose(actorId);
    if (context?.isCurrent && !context.isCurrent()) break;
    if (stock && !stock.isCurrent()) throw new Error("demon_hunter_native_hunter_stock_revoked");
    const currentRole = world.getComponent(actorId, COMPONENT.Role);
    if (
      currentRole !== role ||
      currentRole.role !== rules.role ||
      currentRole.camp !== camp ||
      currentRole.privateState !== privateState ||
      rules.state(currentRole) !== state ||
      rules.policy?.(state) !== policy ||
      context?.deathOriginPhase !== deathPhase ||
      context?.nightEffect !== nightEffect ||
      JSON.stringify(deathSources[actorId] ?? []) !== causeIdentity ||
      !rules.permits(deathSources[actorId] ?? []) ||
      (policy !== undefined &&
        !permitsDeathShot(deathSources[actorId] ?? [], policy, deathPhase)) ||
      !state.canShoot ||
      world.getComponent(actorId, COMPONENT.Alive) !== actorLife ||
      actorLife.alive ||
      aliveLifeVersion(actorLife) !== actorVersion
    )
      continue;
    if (
      selected.kind === "invalid" ||
      !world.isDeathActionOpen(actorId, "shoot", selected.deathActionId)
    )
      continue;
    if (selected.kind === "pass") {
      consume();
      continue;
    }
    if (selected.mappingCurrent && !selected.mappingCurrent()) continue;
    const targetScope = selected.targetScope ?? targets.get(selected.targetId);
    if (selected.mappedMiss) {
      if (
        !selected.mappingCurrent ||
        !targetScope ||
        targetScope.id !== selected.targetId ||
        world.getComponent(targetScope.id, COMPONENT.Alive) !== targetScope.life ||
        targetScope.life.alive ||
        aliveLifeVersion(targetScope.life) !== targetScope.version
      )
        continue;
      consume();
      events.push({
        timestamp: Date.now(),
        type: "death_shot_missed",
        payload: { actorId, reason: "no_effect" },
      });
      continue;
    }
    if (
      !targetScope ||
      targetScope.id !== selected.targetId ||
      !livingNightLife(world, targetScope)
    )
      continue;
    consume();
    if (context?.nightEffect && context.blocksNightShot(selected.targetId)) {
      events.push({
        timestamp: Date.now(),
        type: "death_shot_blocked",
        payload: { actorId, targetId: selected.targetId, reason: "night_protection" },
      });
      continue;
    }
    result.extraDeaths.push(selected.targetId);
    if (context?.nightEffect) (result.nightEffectTargets ??= []).push(selected.targetId);
    result.extraDeathSources[selected.targetId] = [DeathCause.Shot];
    const event = rules.shotEvent(actorId, selected.targetId);
    if (context?.deferShotCommit)
      (result.pendingShots ??= []).push({
        targetScope,
        event,
        isCurrent: () =>
          (context.isCurrent?.() ?? true) &&
          world.getComponent(actorId, COMPONENT.Role) === role &&
          role.role === rules.role &&
          role.camp === camp &&
          role.privateState === privateState &&
          rules.state(role) === state &&
          rules.policy?.(state) === policy &&
          context?.deathOriginPhase === deathPhase &&
          context?.nightEffect === nightEffect &&
          (policy === undefined ||
            permitsDeathShot(deathSources[actorId] ?? [], policy, deathPhase)) &&
          world.getComponent(actorId, COMPONENT.Alive) === actorLife &&
          !actorLife.alive &&
          aliveLifeVersion(actorLife) === actorVersion &&
          JSON.stringify(deathSources[actorId] ?? []) === causeIdentity &&
          world.isDeathActionOpen(actorId, "shoot", selected.deathActionId),
      });
    else events.push(event);
  }
  return result;
}

/**
 * 负责猎人原私有槽的直接读取和既有安装命令。输入为原角色组件与库存；输出保留同一原对象引用。
 * set 先向 hunter 槽赋原值再返回，get 直接访问槽且可能执行调用方 getter；类型断言不作 schema／Proxy 校验。
 * 纯载荷／只读数据结构归公共契约；具体生命周期、付款、写权、玩家投影与检查点仍由原 owner 处理。
 * 本叶不复制或冻结库存，不保存镜像，也不判定请求或死亡开枪许可。
 */
import type { HunterState, HunterReadState } from "@ai-werewolf-arena/game-contract";

import type { RoleComponent } from "../../../../core/domain/components/role";

export function setHunterState(roleComp: RoleComponent, state: HunterState): HunterReadState {
  (roleComp.privateState as { hunter: HunterState })["hunter"] = state;
  return state;
}

export function getHunterState(roleComp: RoleComponent): HunterReadState | undefined {
  return (roleComp.privateState as { readonly hunter?: unknown })["hunter"] as
    HunterReadState | undefined;
}

/**
 * 负责 猎人 的原资料、初始化与运行贡献装配，内建展示只登记语言中立的具体角色标识。
 * 输入为原板子参数、角色组件与请求上下文；输出为分别登记的资料、运行及展示贡献，工具、阶段、初始化和特权 mock 回调保留原引用与顺序。
 * 展示在实际调用时由角色捕获读取原状态并逐片段交纯展示所有者；本模块不授予租约、执行归档或复制状态。
 * 失败和关闭时仍遵守原机制权限与已付费前缀，不把文案当授权。
 */
import { nativeRolePresentation } from "../presentation-contribution";
import { deathActionConfiguration, renderDeathActionPolicy } from "../death_action_policy";
import { roleName, text } from "@ai-werewolf-arena/game-text";
/** 文件说明：猎人角色 profile。 */
import { Camp, Role } from "../../../../core/domain/model";
import { NativeRoleContributions } from "../contracts";
import { getHunterState, setHunterState } from "./state";
import { hunterDeathHook } from "./death_hook";
import { HUNTER_TOOL_SPECS } from "./tool_specs";
import { DEATH_SHOT_REPAIR, validateDeathShot } from "../death_shot";

/** 猎人角色配置。 */
export const HUNTER_ROLE_PROFILE: NativeRoleContributions = {
  metadata: {
    role: Role.Hunter,
    camp: Camp.Good,
    label: roleName("hunter"),
    skillBrief: text("zh-CN", "role.hunter.brief"),
    goodSide: "god",
  },
  runtime: {
    configuration: deathActionConfiguration("hunter"),
    init: (roleComp, ctx) => {
      setHunterState(roleComp, {
        canShoot: true,
        ...(ctx.boardConfig?.hunter?.deathActionPolicy === "awa_knife_or_exile_v1"
          ? { deathActionPolicy: ctx.boardConfig.hunter.deathActionPolicy }
          : {}),
      });
    },
    toolSpecs: HUNTER_TOOL_SPECS,
    validationRules: {
      shoot: (ctx) =>
        validateDeathShot(
          ctx,
          ctx.role.role === Role.Hunter && getHunterState(ctx.role)?.canShoot === true,
        ),
    },
    llmRepair: DEATH_SHOT_REPAIR,
    deathHook: hunterDeathHook,
    baselineAction: (_roleComp, request, pickAliveNotSelf) => {
      if (!request.allowedTools.includes("shoot")) {
        return null;
      }
      const target = pickAliveNotSelf();
      return { name: "shoot", args: { target_id: target } };
    },
  },
  presentation: nativeRolePresentation("hunter"),
};

/**
 * 负责猎人的死亡钩子贡献，在原死亡波中装配枪击选择、死因政策与公开事件。
 * 输入是原 World 玩家、死亡原因、选择回调与当前生命上下文；输出是待提交的枪击死亡和猎人事件。
 * 可用枪击之前的死因、原生命和行动权限检查，以及接受之后的原生枪消费，均由共享枪击所有者负责。
 * 中毒保留原沉默事件，失败或关闭窗口不绕过检查。本钩子不打开死亡权限、不提交目标死亡，
 * 也不切换阶段或关闭死亡波。
 */
import { Role, permitsHunterShot } from "../../../../core/domain/model";
import type { DeathHook } from "../../hooks/hook_registry";
import { getHunterState } from "./state";
import { resolveDeathShots } from "../death_shot";

export const hunterDeathHook: DeathHook = (world, ids, sources, choose, events, context) =>
  resolveDeathShots(
    world,
    ids,
    sources,
    choose,
    events,
    {
      role: Role.Hunter,
      state: getHunterState,
      permits: (sources) => permitsHunterShot(sources),
      policy: (state) => state.deathActionPolicy ?? "awa_qualified_sources_v1",
      poisonEvent: (hunterId) => ({
        timestamp: Date.now(),
        type: "hunter_silent_due_to_poison",
        payload: { hunterId },
      }),
      shotEvent: (hunterId, targetId) => ({
        timestamp: Date.now(),
        type: "hunter_shot",
        payload: { hunterId, targetId },
      }),
    },
    context,
  );

/**
 * 提供猎人状态读取与既有初始化命令的公开入口。输入是调用方原角色对象和安装数据；
 * 输出保留原只读状态引用及初始化写契约。每次读取或安装之前，权限检查与失败、关闭窗口
 * 仍由原调用方和状态所有者负责。本入口仅具名导出本角色状态函数，不校验、复制、冻结或存储状态。
 */
export { getHunterState, setHunterState } from "./state";

/**
 * 负责狼王原私有槽的直接读取和既有安装命令。输入为原角色组件与库存；输出保留同一原对象引用。
 * set 先向 wolf_king 槽赋原值再返回，get 直接访问槽且可能执行调用方 getter；类型断言不作 schema／Proxy 校验。
 * 纯载荷／只读数据结构归公共契约；具体生命周期、付款、写权、玩家投影与检查点仍由原 owner 处理。
 * 本叶不复制或冻结库存，不保存镜像，也不判定请求或死亡开枪许可。
 */
import type { WolfKingState, WolfKingReadState } from "@ai-werewolf-arena/game-contract";

import type { RoleComponent } from "../../../../core/domain/components/role";

export function setWolfKingState(roleComp: RoleComponent, state: WolfKingState): WolfKingReadState {
  (roleComp.privateState as { wolf_king: WolfKingState })["wolf_king"] = state;
  return state;
}

export function getWolfKingState(roleComp: RoleComponent): WolfKingReadState | undefined {
  return (roleComp.privateState as { readonly wolf_king?: unknown })["wolf_king"] as
    WolfKingReadState | undefined;
}

/**
 * 负责 狼王 的原资料、初始化与运行贡献装配，内建展示只登记语言中立的具体角色标识。
 * 输入为原板子参数、角色组件与请求上下文；输出为分别登记的资料、运行及展示贡献，工具、阶段、初始化和特权 mock 回调保留原引用与顺序。
 * 展示在实际调用时由角色捕获读取原状态并逐片段交纯展示所有者；本模块不授予租约、执行归档或复制状态。
 * 失败和关闭时仍遵守原机制权限与已付费前缀，不把文案当授权。
 */
import { nativeRolePresentation } from "../presentation-contribution";
import { deathActionConfiguration, renderDeathActionPolicy } from "../death_action_policy";
import { roleName, text } from "@ai-werewolf-arena/game-text";
import { Role, permitsDeathShot } from "../../../../core/domain/model";
import type { NativeRoleContributions } from "../contracts";
import { getWolfKingState, setWolfKingState } from "./state";
import {
  resolveDeathShots,
  DEATH_SHOT_TOOL_SPECS,
  DEATH_SHOT_REPAIR,
  validateDeathShot,
} from "../death_shot";
import { ORDINARY_WOLF_CONTRIBUTIONS } from "../wolf/ability-ports";

/** AWA 狼王 1.0：普通狼队权限，加一次满足死亡来源条件的开枪机会。 */
export const WOLF_KING_ROLE_PROFILE: NativeRoleContributions = {
  metadata: {
    ...ORDINARY_WOLF_CONTRIBUTIONS.metadata,
    role: Role.WolfKing,
    label: roleName("wolf_king"),
    skillBrief: text("zh-CN", "role.wolf_king.brief"),
  },
  runtime: {
    ...ORDINARY_WOLF_CONTRIBUTIONS.runtime,
    configuration: deathActionConfiguration("wolfKing"),
    init: (role, ctx) => {
      setWolfKingState(role, {
        canShoot: true,
        ...(ctx.boardConfig?.wolfKing?.deathActionPolicy !== undefined &&
        ctx.boardConfig.wolfKing.deathActionPolicy !== "awa_qualified_sources_v1"
          ? { deathActionPolicy: ctx.boardConfig.wolfKing.deathActionPolicy }
          : {}),
      });
    },
    toolSpecs: [...ORDINARY_WOLF_CONTRIBUTIONS.runtime.toolSpecs!, ...DEATH_SHOT_TOOL_SPECS],
    validationRules: {
      ...ORDINARY_WOLF_CONTRIBUTIONS.runtime.validationRules,
      shoot: (ctx) =>
        validateDeathShot(
          ctx,
          ctx.role.role === Role.WolfKing && getWolfKingState(ctx.role)?.canShoot === true,
        ),
    },
    llmRepair: {
      coerce: { ...ORDINARY_WOLF_CONTRIBUTIONS.runtime.llmRepair?.coerce, ...DEATH_SHOT_REPAIR.coerce },
    },
    deathHook: (world, ids, sources, choose, events, context) =>
      resolveDeathShots(
        world,
        ids,
        sources,
        choose,
        events,
        {
          role: Role.WolfKing,
          state: getWolfKingState,
          permits: (sources) => permitsDeathShot(sources),
          policy: (state) => state.deathActionPolicy ?? "awa_qualified_sources_v1",
          shotEvent: (actorId, targetId) => ({
            timestamp: Date.now(),
            type: "wolf_king_shot",
            payload: { actorId, targetId },
          }),
        },
        context,
      ),
    baselineAction: (role, request, pickAliveNotSelf, pickAliveByCamp, locale) =>
      request.allowedTools.includes("shoot")
        ? { name: "shoot", args: { target_id: pickAliveByCamp("good") ?? pickAliveNotSelf() } }
        : ORDINARY_WOLF_CONTRIBUTIONS.runtime.baselineAction!(
            role,
            request,
            pickAliveNotSelf,
            pickAliveByCamp,
            locale,
          ),
  },
  presentation: nativeRolePresentation("wolf_king"),
};

/**
 * 提供狼王原状态读取函数的公开入口。输入是调用方在原读取时点传入的角色对象；
 * 输出保留同一只读状态引用和原 getter 契约。读取之前的权限检查与失败、关闭窗口
 * 仍由原调用方负责。本入口仅具名导出本角色函数，不安装、校验、复制、冻结或存储状态。
 */
export { getWolfKingState } from "./state";

/**
 * 负责机械狼的学习模板、所属槽安装、模式／刀资源提交和玩家投影。输入为原角色、状态与日次；
 * 输出保留原学习、模式、刀权字段以及存储引用，公开 DTO 类型独立归公共契约。
 * 模板创建不克隆其他玩家库存；本模块只写 mechanical_wolf 及其资源，不替换角色容器或授予请求许可。
 * 实际开夜才武装枪和处理首刀过期；提交按原字段顺序，异常不回滚此前状态。
 */
import type {
  MechanicalMode,
  MechanicalSkill,
  MechanicalLearning,
  MechanicalState,
  MechanicalReadSkill,
  MechanicalReadLearning,
  MechanicalReadState,
} from "@ai-werewolf-arena/game-contract";

import type { PlayerMechanicalState } from "@ai-werewolf-arena/game-contract/player-state-views";
import type { InspectionResult, RoleId } from "@ai-werewolf-arena/game-contract";
import type { RoleComponent } from "../../../../core/domain/components/role";
import type { EntityId } from "../../../../core/domain/identity";
import { copyAbilityData } from "../abilities";

export function freshMechanicalState(): MechanicalState {
  return {
    learned: null,
    mimicClosedDay: null,
    mode: null,
    hasInheritedKnife: false,
    firstKnifeNight: null,
    skillClosedDay: null,
  };
}
/** 从所属槽返回原存储引用；类型只读不等于复制或运行时冻结，写入仍由具名提交函数负责。 */
export function getMechanicalState(
  role: RoleComponent | undefined,
): MechanicalReadState | undefined {
  return (role as { readonly privateState: { readonly mechanical_wolf?: unknown } } | undefined)
    ?.privateState.mechanical_wolf as MechanicalReadState | undefined;
}
export function setMechanicalState(
  role: RoleComponent,
  state: MechanicalState,
): MechanicalReadState {
  const owned = copyAbilityData(state);
  (role.privateState as { mechanical_wolf: MechanicalState }).mechanical_wolf = owned;
  return owned;
}
export function mechanicalLearning(
  targetId: EntityId,
  role: RoleId,
  day: number,
): MechanicalLearning {
  let skill: MechanicalSkill;
  switch (role) {
    case "villager":
      skill = { kind: "villager" };
      break;
    case "psychic":
      skill = { kind: "inspection", history: [] };
      break;
    case "witch":
      skill = { kind: "poison", remaining: 1 };
      break;
    case "guard":
      skill = { kind: "guard", lastTarget: null, lastGuardDay: null };
      break;
    case "hunter":
      skill = { kind: "hunter", canShoot: true, armed: false };
      break;
    case "wolf":
      skill = { kind: "wolf", extraKnife: "available" };
      break;
    default:
      throw new Error("mechanical_learning_role_not_supported");
  }
  return { targetId, role, day, readyOnNight: day + 1, skill };
}

/** 开局／死亡检查点调用此处一次提交继承字段；后续刀权资格和事实发布仍由原调用方负责。 */
export function recordMechanicalInheritance(state: MechanicalReadState, day: number): boolean {
  if (state.hasInheritedKnife) return false;
  (state as { hasInheritedKnife: boolean }).hasInheritedKnife = true;
  (state as { firstKnifeNight: number | null }).firstKnifeNight = Math.max(2, day + 1);
  return true;
}

export function canMechanicalMimic(state: MechanicalReadState, day: number): boolean {
  return (
    day >= 1 &&
    state.learned === null &&
    (state.mimicClosedDay === null || state.mimicClosedDay < day)
  );
}

/** 合法等待只关闭本夜学习机会，保留整局一次的学习库存。 */
export function closeMechanicalMimic(state: MechanicalReadState, day: number): boolean {
  if (!canMechanicalMimic(state, day)) return false;
  (state as { mimicClosedDay: number | null }).mimicClosedDay = day;
  return true;
}

export function learnMechanicalRole(
  state: MechanicalReadState,
  targetId: EntityId,
  role: RoleId,
  day: number,
): boolean {
  if (!canMechanicalMimic(state, day)) return false;
  const learned = mechanicalLearning(targetId, role, day);
  if (
    learned.skill.kind === "wolf" &&
    state.firstKnifeNight !== null &&
    day >= state.firstKnifeNight
  ) {
    (learned.skill as { extraKnife: "available" | "spent" | "expired" }).extraKnife = "expired";
  }
  (state as { learned: MechanicalReadState["learned"] }).learned = learned;
  (state as { mimicClosedDay: number | null }).mimicClosedDay = day;
  return true;
}

/** 进入实际夜才武装被动枪，并将已经过去的首刀窗口标为过期，不能靠日次跳转补刀。 */
export function advanceMechanicalNight(state: MechanicalReadState, day: number): void {
  const learned = state.learned;
  if (!learned) return;
  if (learned.skill.kind === "hunter" && day >= learned.readyOnNight)
    (learned.skill as { armed: boolean }).armed = true;
  if (
    learned.skill.kind === "wolf" &&
    learned.skill.extraKnife === "available" &&
    state.firstKnifeNight !== null &&
    day > state.firstKnifeNight
  ) {
    (learned.skill as { extraKnife: "available" | "spent" | "expired" }).extraKnife = "expired";
  }
}

export function canSelectMechanicalMode(state: MechanicalReadState, day: number): boolean {
  return day >= 2 && (state.mode === null || state.mode.day < day);
}

/** 等待沿用技能模式选择；本夜第二次选择被拒，不重写第一次模式。 */
export function selectMechanicalMode(
  state: MechanicalReadState,
  day: number,
  mode: MechanicalMode,
): boolean {
  if (!canSelectMechanicalMode(state, day)) return false;
  (state as { mode: MechanicalReadState["mode"] }).mode = { day, kind: mode };
  const learned = state.learned;
  if (
    mode === "skill" &&
    state.firstKnifeNight === day &&
    learned?.skill.kind === "wolf" &&
    learned.skill.extraKnife === "available"
  ) {
    (learned.skill as { extraKnife: "available" | "spent" | "expired" }).extraKnife = "expired";
  }
  return true;
}

export function mechanicalSkillForNight(
  state: MechanicalReadState,
  day: number,
): MechanicalReadSkill | undefined {
  if (
    day < 2 ||
    state.mode?.day !== day ||
    state.mode.kind !== "skill" ||
    !state.learned ||
    state.learned.readyOnNight > day ||
    (state.skillClosedDay !== null && state.skillClosedDay >= day)
  )
    return undefined;
  return state.learned.skill;
}

export function closeMechanicalSkill(state: MechanicalReadState, day: number): boolean {
  if (!mechanicalSkillForNight(state, day)) return false;
  (state as { skillClosedDay: number | null }).skillClosedDay = day;
  return true;
}

/** 调用方另行核对当前唯一活狼的刀权及原模式许可；本字段查询不授予出刀资格。 */
export function mechanicalKnifeSelected(state: MechanicalReadState, day: number): boolean {
  return (
    day >= 2 &&
    state.hasInheritedKnife &&
    state.firstKnifeNight !== null &&
    day >= state.firstKnifeNight &&
    state.mode?.day === day &&
    state.mode.kind === "kill"
  );
}

export function canMechanicalExtraKnife(state: MechanicalReadState, day: number): boolean {
  const learned = state.learned;
  return (
    mechanicalKnifeSelected(state, day) &&
    state.firstKnifeNight === day &&
    learned !== null &&
    learned.readyOnNight <= day &&
    learned.skill.kind === "wolf" &&
    learned.skill.extraKnife === "available"
  );
}

/** 按相邻实际夜与目标编号判重复守护，同编号复活不会清除该历史；两字段按原顺序写入。 */
export function chooseMechanicalGuard(
  skill: Extract<MechanicalReadSkill, { kind: "guard" }>,
  targetId: EntityId | null,
  day: number,
): { failed: boolean } {
  const failed =
    targetId !== null && skill.lastTarget === targetId && skill.lastGuardDay === day - 1;
  (skill as { lastTarget: EntityId | null }).lastTarget = targetId;
  (skill as { lastGuardDay: number | null }).lastGuardDay = day;
  return { failed };
}

/** 玩家投影逐字段列出知识和资源摘要；以后新增的全局调试字段不会自动成为玩家输入。 */
export function projectMechanicalState(state: MechanicalReadState): PlayerMechanicalState {
  const learned = state.learned;
  let skill: MechanicalSkill | undefined;
  if (learned)
    switch (learned.skill.kind) {
      case "villager":
        skill = { kind: "villager" };
        break;
      case "inspection":
        skill = {
          kind: "inspection",
          history: learned.skill.history.map((report) => ({
            day: report.day,
            targetId: report.targetId,
            result: { kind: "role", role: report.result.role },
          })),
        };
        break;
      case "poison":
        skill = { kind: "poison", remaining: learned.skill.remaining };
        break;
      case "guard":
        skill = {
          kind: "guard",
          lastTarget: learned.skill.lastTarget,
          lastGuardDay: learned.skill.lastGuardDay,
        };
        break;
      case "hunter":
        skill = { kind: "hunter", canShoot: learned.skill.canShoot, armed: learned.skill.armed };
        break;
      case "wolf":
        skill = { kind: "wolf", extraKnife: learned.skill.extraKnife };
        break;
    }
  return {
    learned:
      learned && skill
        ? {
            targetId: learned.targetId,
            role: learned.role,
            day: learned.day,
            readyOnNight: learned.readyOnNight,
            skill,
          }
        : null,
    mimicClosedDay: state.mimicClosedDay,
    mode: state.mode ? { day: state.mode.day, kind: state.mode.kind } : null,
    hasInheritedKnife: state.hasInheritedKnife,
    firstKnifeNight: state.firstKnifeNight,
    skillClosedDay: state.skillClosedDay,
  };
}

/** 调用方保留查验与当前性检查；先读取原历史容器，再读取 target.id 并追加一行。 */
export function recordMechanicalInspection(
  skill: Extract<MechanicalReadSkill, { kind: "inspection" }>,
  day: number,
  target: { readonly id: EntityId },
  result: Extract<InspectionResult, { kind: "role" }>,
): void {
  (skill.history as Extract<MechanicalSkill, { kind: "inspection" }>["history"]).push({
    day,
    targetId: target.id,
    result: { ...result },
  });
}
/** 原毒提案与标记之后提交库存消耗，不增加复检、回滚或新的付款时点。 */
export function consumeMechanicalPoison(
  skill: Extract<MechanicalReadSkill, { kind: "poison" }>,
): void {
  (skill as { remaining: 0 | 1 }).remaining = 0;
}
/** 调用方保留原攻击可空目标与完成顺序；非空目标标花费，空目标只按原机械首刀规则过期。 */
export function closeMechanicalExtraKnife(
  skill: Extract<MechanicalReadSkill, { kind: "wolf" }>,
  target: unknown,
): void {
  (skill as { extraKnife: "available" | "spent" | "expired" }).extraKnife = target
    ? "spent"
    : "expired";
}

/**
 * Owns Mechanical Wolf's captured learned-gun contribution to ordered death shots.
 * Inputs are original state/learning/gun references and death contexts; outputs
 * preserve identity rechecks, cause eligibility and existing shot events.
 * Stored resources are read-only here; the shared death-shot owner consumes the
 * original gun, and this hook never clones state, refunds stock or grants a new lease.
 * After an actual death wave, the resolver rechecks currentness before and after
 * selecting a shot; stale or terminal windows never reopen a consumed learned gun.
 */

import type {
  MechanicalReadState as MechanicalState,
  MechanicalReadLearning as MechanicalLearning,
  MechanicalReadSkill as MechanicalSkill,
} from "@ai-werewolf-arena/game-contract";
import { Camp, Role, permitsDeathShot } from "../../../../core/domain/model";
import type { RoleComponent } from "../../../../core/domain/components/role";
import type { DeathHook } from "../../hooks/hook_registry";
import { resolveDeathShots } from "../death_shot";
import { getMechanicalState } from "./state";

export const mechanicalDeathHook: DeathHook = (world, ids, sources, choose, events, context) => {
  const owners = new Map<
    RoleComponent,
    {
      state: MechanicalState;
      learning: MechanicalLearning;
      gun: Extract<MechanicalSkill, { kind: "hunter" }>;
    }
  >();
  return resolveDeathShots(
    world,
    ids,
    sources,
    choose,
    events,
    {
      role: Role.MechanicalWolf,
      state: (role) => {
        const state = getMechanicalState(role),
          learning = state?.learned,
          skill = learning?.skill;
        if (
          role.camp !== Camp.Wolf ||
          !state ||
          !learning ||
          skill?.kind !== "hunter" ||
          !skill.armed
        )
          return undefined;
        const prior = owners.get(role);
        if (prior && (state !== prior.state || learning !== prior.learning || skill !== prior.gun))
          return undefined;
        if (!prior) owners.set(role, { state, learning, gun: skill });
        return skill;
      },
      permits: permitsDeathShot,
      shotEvent: (actorId, targetId) => ({
        timestamp: Date.now(),
        type: "mechanical_shot",
        payload: { actorId, targetId },
      }),
    },
    context,
  );
};

/**
 * 提供机械狼刀权继承的公开规则贡献。输入是在实际死亡提交之后传入的原 World、日期和事件；
 * 输出保留原学习模式下的继承写入与事实顺序。写权限与失败检查由机械狼继承所有者负责，
 * 本入口仅具名导出原函数，不建立第二份状态、不复制学习结果或重新打开已关闭窗口。
 * 状态与玩家投影查询保留原 getter 时点；潜在阶段声明不消费模式或重新安装技能。
 */

export { refreshMechanicalInheritance } from "./inheritance";

export { getMechanicalState } from "./state";

export { projectMechanicalState } from "./state";

/**
 * 负责觉醒隐狼的学习模板、所属槽安装、激活／技能资源提交和玩家投影。输入为原角色、状态与实际夜；
 * 输出保留激活、技能和原存储引用，公开 DTO 类型独立归公共契约。
 * 只写 awakened_hidden_wolf 及其学习资源，不扩大角色容器写权、重抽模板、退款或授予请求许可。
 * 激活与主动技能生效夜分别保存；次数／关窗和字段提交保持原顺序，失败保留已写前缀。
 */
import type {
  AwakenedSkill,
  AwakenedActiveSkill,
  AwakenedTemplateRole,
  AwakenedLearning,
  AwakenedState,
  AwakenedReadSkill,
  AwakenedReadActiveSkill,
  AwakenedReadLearning,
  AwakenedReadState,
} from "@ai-werewolf-arena/game-contract";

import type { PlayerAwakenedState } from "@ai-werewolf-arena/game-contract/player-state-views";
import type { RoleId } from "@ai-werewolf-arena/game-contract";
import type { RoleComponent } from "../../../../core/domain/components/role";
import type { EntityId } from "../../../../core/domain/identity";
import { copyAbilityData } from "../abilities";

const validDay = (day: number) =>
  Number.isSafeInteger(day) && day >= 1 && day < Number.MAX_SAFE_INTEGER;
const validTarget = (id: number) => Number.isSafeInteger(id) && id >= 1;
export function freshAwakenedState(): AwakenedState {
  return {
    learned: null,
    mimicClosedDay: null,
    skillClosedDay: null,
    hasInheritedKnife: false,
    firstKnifeNight: null,
  };
}
export function getAwakenedState(role: RoleComponent | undefined): AwakenedReadState | undefined {
  return (
    role as { readonly privateState: { readonly awakened_hidden_wolf?: unknown } } | undefined
  )?.privateState.awakened_hidden_wolf as AwakenedReadState | undefined;
}
/** 复制数据后安装到原私有槽；请求许可和原体证明另有所有者，不随此数据复制。 */
export function setAwakenedState(role: RoleComponent, state: AwakenedState): AwakenedReadState {
  const owned = copyAbilityData(state);
  (role.privateState as { awakened_hidden_wolf: AwakenedState }).awakened_hidden_wolf = owned;
  return owned;
}

export function awakenedLearning(targetId: EntityId, role: RoleId, day: number): AwakenedLearning {
  if (!validDay(day) || !validTarget(targetId)) throw new Error("awakened_learning_input_invalid");
  let skill: AwakenedSkill;
  switch (role) {
    case "villager":
      skill = { kind: "villager" };
      break;
    case "mirror_girl":
      skill = { kind: "inspection", abilityId: null };
      break;
    case "witch":
      skill = { kind: "poison", remaining: 1 };
      break;
    case "guard":
      skill = { kind: "guard", lastTarget: null, lastGuardDay: null };
      break;
    case "hunter":
      skill = { kind: "hunter", canShoot: true, armed: false };
      break;
    case "wolf":
      skill = { kind: "wolf", extraKnife: "available" };
      break;
    default:
      throw new Error("awakened_learning_role_not_supported");
  }
  return { targetId, role, day, activationNight: null, activeFromNight: null, skill };
}
export function canAwakenedMimic(state: AwakenedReadState, day: number): boolean {
  return (
    validDay(day) &&
    state.learned === null &&
    (state.mimicClosedDay === null || state.mimicClosedDay < day)
  );
}
export function closeAwakenedMimic(state: AwakenedReadState, day: number): boolean {
  if (!canAwakenedMimic(state, day)) return false;
  (state as { mimicClosedDay: number | null }).mimicClosedDay = day;
  return true;
}
export function learnAwakenedRole(
  state: AwakenedReadState,
  targetId: EntityId,
  role: RoleId,
  day: number,
): boolean {
  if (!canAwakenedMimic(state, day)) return false;
  const learned = awakenedLearning(targetId, role, day);
  (state as { learned: AwakenedReadState["learned"] }).learned = learned;
  (state as { mimicClosedDay: number | null }).mimicClosedDay = day;
  return true;
}

/** 只在实际夜末提交激活；选择模板或进入以后日次不会补造激活夜。 */
export function activateAwakenedLearning(
  state: AwakenedReadState,
  night: number,
  mirrorAbilityId?: string,
): boolean {
  const learned = state.learned;
  if (!learned || !validDay(night) || night < learned.day || learned.activationNight !== null)
    return false;
  if (
    learned.skill.kind === "inspection" &&
    (typeof mirrorAbilityId !== "string" || !mirrorAbilityId.length)
  )
    return false;
  if (learned.skill.kind !== "inspection" && mirrorAbilityId !== undefined) return false;
  if (learned.skill.kind === "inspection")
    (learned.skill as { abilityId: string | null }).abilityId = mirrorAbilityId!;
  if (learned.skill.kind === "hunter") (learned.skill as { armed: boolean }).armed = true;
  (learned as { activationNight: number | null }).activationNight = night;
  (learned as { activeFromNight: number | null }).activeFromNight = night + 1;
  return true;
}

/** 被动猎人枪的可用性从枪自身读取；主动技能要在实际激活后的生效夜查询。 */
export function awakenedSkillForNight(
  state: AwakenedReadState,
  night: number,
): AwakenedReadActiveSkill | undefined {
  const learned = state.learned;
  if (
    !validDay(night) ||
    !learned ||
    learned.activationNight === null ||
    learned.activeFromNight === null ||
    night < learned.activeFromNight ||
    (state.skillClosedDay !== null && state.skillClosedDay >= night)
  )
    return undefined;
  if (learned.skill.kind === "poison" && learned.skill.remaining === 0) return undefined;
  if (learned.skill.kind === "wolf" && learned.skill.extraKnife === "spent") return undefined;
  return learned.skill.kind === "poison" ||
    learned.skill.kind === "guard" ||
    learned.skill.kind === "wolf"
    ? learned.skill
    : undefined;
}
export function closeAwakenedSkill(state: AwakenedReadState, night: number): boolean {
  if (!awakenedSkillForNight(state, night)) return false;
  (state as { skillClosedDay: number | null }).skillClosedDay = night;
  return true;
}

/** 装配／死亡检查点一次提交继承；它不依赖学习或技能选择，不消费学习资源。 */
export function recordAwakenedInheritance(state: AwakenedReadState, day: number): boolean {
  if (!validDay(day) || state.hasInheritedKnife) return false;
  (state as { hasInheritedKnife: boolean }).hasInheritedKnife = true;
  (state as { firstKnifeNight: number | null }).firstKnifeNight = Math.max(2, day + 1);
  return true;
}
export function awakenedKnifeReady(state: AwakenedReadState, night: number): boolean {
  return (
    validDay(night) &&
    state.hasInheritedKnife &&
    state.firstKnifeNight !== null &&
    night >= state.firstKnifeNight
  );
}
/** 调用方还核对当前原持有者与唯一活狼许可；这里的字段条件不单独授予刀权。 */
export function canAwakenedExtraKnife(state: AwakenedReadState, night: number): boolean {
  const skill = awakenedSkillForNight(state, night);
  return (
    awakenedKnifeReady(state, night) && skill?.kind === "wolf" && skill.extraKnife === "available"
  );
}
/** 空刀只关闭本夜机会；实际非空攻击才花费整局一次的额外刀库存。 */
export function chooseAwakenedAttack(
  state: AwakenedReadState,
  targetId: EntityId | null,
  night: number,
): boolean {
  if (!canAwakenedExtraKnife(state, night) || (targetId !== null && !validTarget(targetId)))
    return false;
  const skill = state.learned!.skill;
  if (skill.kind !== "wolf") return false;
  if (targetId !== null) (skill as { extraKnife: "available" | "spent" }).extraKnife = "spent";
  (state as { skillClosedDay: number | null }).skillClosedDay = night;
  return true;
}

export function chooseAwakenedGuard(
  state: AwakenedReadState,
  targetId: EntityId | null,
  night: number,
): boolean {
  const skill = awakenedSkillForNight(state, night);
  if (
    skill?.kind !== "guard" ||
    (targetId !== null && !validTarget(targetId)) ||
    (targetId !== null && skill.lastTarget === targetId && skill.lastGuardDay === night - 1)
  )
    return false;
  (skill as { lastTarget: EntityId | null }).lastTarget = targetId;
  (skill as { lastGuardDay: number | null }).lastGuardDay = night;
  (state as { skillClosedDay: number | null }).skillClosedDay = night;
  return true;
}
/** 合法的无工具等待也按空目标结束本夜守护，打断连续守同一编号的历史。 */
export function skipAwakenedSkill(state: AwakenedReadState, night: number): boolean {
  const skill = awakenedSkillForNight(state, night);
  if (!skill) return false;
  if (skill.kind === "guard") return chooseAwakenedGuard(state, null, night);
  if (skill.kind === "wolf") return chooseAwakenedAttack(state, null, night);
  return closeAwakenedSkill(state, night);
}
export function useAwakenedPoison(state: AwakenedReadState, night: number): boolean {
  const skill = awakenedSkillForNight(state, night);
  if (skill?.kind !== "poison" || skill.remaining !== 1) return false;
  (skill as { remaining: 0 | 1 }).remaining = 0;
  (state as { skillClosedDay: number | null }).skillClosedDay = night;
  return true;
}

/** 只投影列出的玩家字段；魔镜查验历史与库存由其能力实例唯一拥有，不复制进学习模板。 */
export function projectAwakenedState(state: AwakenedReadState): PlayerAwakenedState {
  const learned = state.learned;
  let skill: AwakenedSkill | undefined;
  if (learned)
    switch (learned.skill.kind) {
      case "villager":
        skill = { kind: "villager" };
        break;
      case "inspection":
        skill = { kind: "inspection", abilityId: learned.skill.abilityId };
        break;
      case "poison":
        skill = { kind: "poison", remaining: learned.skill.remaining };
        break;
      case "guard":
        skill = {
          kind: "guard",
          lastTarget: learned.skill.lastTarget,
          lastGuardDay: learned.skill.lastGuardDay,
        };
        break;
      case "hunter":
        skill = { kind: "hunter", armed: learned.skill.armed, canShoot: learned.skill.canShoot };
        break;
      case "wolf":
        skill = { kind: "wolf", extraKnife: learned.skill.extraKnife };
        break;
    }
  return {
    learned:
      learned && skill
        ? {
            targetId: learned.targetId,
            role: learned.role,
            day: learned.day,
            activationNight: learned.activationNight,
            activeFromNight: learned.activeFromNight,
            skill,
          }
        : null,
    mimicClosedDay: state.mimicClosedDay,
    skillClosedDay: state.skillClosedDay,
    hasInheritedKnife: state.hasInheritedKnife,
    firstKnifeNight: state.firstKnifeNight,
  };
}

/**
 * Owns Awakened Hidden Wolf's captured activated-gun death-shot contribution.
 * Inputs are original learned state, activation metadata and death contexts;
 * outputs preserve the original pointer/metadata rechecks and shot publication.
 * Read views carry no write permission; consumption stays in the existing shared
 * death-shot owner and this hook never reactivates or refunds a learned template.
 * After an actual death wave, the resolver rechecks currentness before and after
 * selecting a shot; stale or terminal windows never reopen a consumed learned gun.
 */

import type {
  AwakenedReadState as AwakenedState,
  AwakenedReadLearning as AwakenedLearning,
  AwakenedReadSkill as AwakenedSkill,
} from "@ai-werewolf-arena/game-contract";
import { Camp, Role, permitsDeathShot } from "../../../../core/domain/model";
import type { RoleComponent } from "../../../../core/domain/components/role";
import type { DeathHook } from "../../hooks/hook_registry";
import { resolveDeathShots } from "../death_shot";
import { getAwakenedState } from "./state";

export const awakenedDeathHook: DeathHook = (world, ids, sources, choose, events, context) => {
  const owners = new Map<
    RoleComponent,
    {
      state: AwakenedState;
      learned: AwakenedLearning;
      gun: Extract<AwakenedSkill, { kind: "hunter" }>;
      targetId: number;
      role: AwakenedLearning["role"];
      day: number;
      activationNight: number;
      activeFromNight: number;
    }
  >();
  return resolveDeathShots(
    world,
    ids,
    sources,
    choose,
    events,
    {
      role: Role.AwakenedHiddenWolf,
      state: (role) => {
        const state = getAwakenedState(role),
          learned = state?.learned,
          gun = learned?.skill;
        if (
          role.camp !== Camp.Wolf ||
          !state ||
          !learned ||
          learned.role !== Role.Hunter ||
          learned.activationNight === null ||
          learned.activeFromNight === null ||
          gun?.kind !== "hunter" ||
          !gun.armed
        )
          return undefined;
        const prior = owners.get(role);
        if (
          prior &&
          (state !== prior.state ||
            learned !== prior.learned ||
            gun !== prior.gun ||
            learned.targetId !== prior.targetId ||
            learned.role !== prior.role ||
            learned.day !== prior.day ||
            learned.activationNight !== prior.activationNight ||
            learned.activeFromNight !== prior.activeFromNight)
        )
          return undefined;
        if (!prior)
          owners.set(role, {
            state,
            learned,
            gun,
            targetId: learned.targetId,
            role: learned.role,
            day: learned.day,
            activationNight: learned.activationNight,
            activeFromNight: learned.activeFromNight,
          });
        return gun;
      },
      permits: permitsDeathShot,
      shotEvent: (actorId, targetId) => ({
        timestamp: Date.now(),
        type: "player_shot",
        payload: { actorId, targetId },
      }),
    },
    context,
  );
};

